    final word = match.group(0)!;
    raw++;
    if (stops.contains(word)) {
      stopwords++;
    } else if (word.length == 1) {
      short++;
    } else {
      words.add(word);
    }
  }
  bigrams = [for (var i = 0; i + 1 < words.length; i++) '${words[i]}_${words[i + 1]}'];
  bigramTerms = [...words, ...bigrams];
}
